    def retranslateUi(self, Form):
        _translate = QtCore.QCoreApplication.translate
        self.btn_set_to_default.setToolTip(_translate("Form", "<p>Sets every setting of the Structure, Motion and Batch tabs back to its default. The open image, its metadata (pixel size, frame time, axes, channel), its results and the batch root folder are not changed. To reset a single tab, use 'Reset tab defaults' on that tab.</p>"))
        self.btn_export_parameters.setToolTip(_translate("Form", "<p>Saves all current settings of the Structure, Motion and Batch tabs (including the batch root folder) to the parameter file in the field, overwriting it. Load them later with 'Import', e.g. to analyse another experiment with the same settings.</p>"))
        self.btn_import_parameters.setToolTip(_translate("Form", "<p>Loads the settings from the parameter file in the field into the Structure, Motion and Batch tabs (including the batch root folder). Settings missing from the file keep their current values; values of the wrong type are listed and skipped. The open image and its results are not changed; run the analysis again to apply the new settings.</p>"))
        self.btn_search_parameters_file.setToolTip(_translate("Form", "<p>Pick a parameter file (.json) in a file dialog; its path goes into the field. To start a new file, type a new name: an empty file is created at once, ready for 'Export'. A file that is not valid JSON is refused.</p>"))
        self.btn_store_metadata.setToolTip(_translate("Form", "<p>Applies the frame time, pixel size, axes and channel of this row to the open image and saves them in its .ome.zarr store, so they are used again next time. A new axes order or channel reads the image again. A new pixel size on an analysed file, or a new frame time with motion results, makes the results invalid; you are asked before they are deleted. Invalid entries turn red and nothing is applied.</p>"))
        self.spinbox_channel.setToolTip(_translate("Form", "<p>Which colour channel holds the sarcomere stain (Z-bands, e.g. α-actinin), counted from 0. Active only when Axes contains C; until you choose, channel 0 is used. A change re-reads the image at once with the new channel; if the file has results, you are asked first to delete them.</p>"))
        self.label_4.setToolTip(_translate("Form", "<p>Which colour channel holds the sarcomere stain (Z-bands, e.g. α-actinin), counted from 0. Active only when Axes contains C; until you choose, channel 0 is used. A change re-reads the image at once with the new channel; if the file has results, you are asked first to delete them.</p>"))
        self.le_axes.setToolTip(_translate("Form", "<p>Order of the image dimensions, one letter each: T time, Z depth, C channel, Y rows, X columns (e.g. TYX for a movie, YX for an image, TCYX for a multi-channel movie). Detected from the file; correct it if the image looks wrong, e.g. movie frames shown as channels. The number of letters must match the image dimensions. Applied with 'Save metadata', which reads the image again; if the file has results, you are asked first to delete them.</p>"))
        self.label_5.setToolTip(_translate("Form", "<p>Order of the image dimensions, one letter each: T time, Z depth, C channel, Y rows, X columns (e.g. TYX for a movie, YX for an image, TCYX for a multi-channel movie). Detected from the file; correct it if the image looks wrong, e.g. movie frames shown as channels. The number of letters must match the image dimensions. Applied with 'Save metadata', which reads the image again; if the file has results, you are asked first to delete them.</p>"))
        self.le_pixel_size.setToolTip(_translate("Form", "<p>Edge length of one image pixel, in µm per pixel. Read from the file (OME, ImageJ or TIFF resolution tags) when present; a red field means it is missing or implausible. Every length in µm depends on it. Values outside 0.01–0.5 µm are refused. Applied on Enter or when you leave the field; on an analysed file you are asked first, because the results must be deleted and recomputed.</p>"))
        self.label_3.setToolTip(_translate("Form", "<p>Edge length of one image pixel, in µm per pixel. Read from the file (OME, ImageJ or TIFF resolution tags) when present; a red field means it is missing or implausible. Every length in µm depends on it. Values outside 0.01–0.5 µm are refused. Applied on Enter or when you leave the field; on an analysed file you are asked first, because the results must be deleted and recomputed.</p>"))
        self.le_frame_time.setToolTip(_translate("Form", "<p>Time between two frames of the movie, in seconds per frame (1 / frame rate; 0.01 s at 100 frames/s). Read from the file when it is stored there; otherwise enter it. Only the motion analysis uses it: velocities, beating rate and all contraction times scale with it, and it refuses to run without it. Applied on Enter or when you leave the field. If motion results exist, a change asks to delete them and re-analyse.</p>"))
        self.label_2.setToolTip(_translate("Form", "<p>Time between two frames of the movie, in seconds per frame (1 / frame rate; 0.01 s at 100 frames/s). Read from the file when it is stored there; otherwise enter it. Only the motion analysis uses it: velocities, beating rate and all contraction times scale with it, and it refuses to run without it. Applied on Enter or when you leave the field. If motion results exist, a change asks to delete them and re-analyse.</p>"))
        Form.setWindowTitle(_translate("Form", "Form"))
        self.groupBox.setTitle(_translate("Form", "File Selection"))
        self.label.setToolTip(_translate("Form", "<p>Path of the image to open: a .tif/.tiff image or movie, or a .ome.zarr results folder. Paste or type the path and press Enter, use the buttons on the right, or drop the file onto the viewer. If a .tif already has a &lt;name&gt;.ome.zarr folder next to it, its saved results and metadata are loaded too; otherwise that folder is created, and all results of this image are saved there.</p>"))
        self.label.setText(_translate("Form", "Input"))
        self.le_cell_file.setToolTip(_translate("Form", "<p>Path of the image to open: a .tif/.tiff image or movie, or a .ome.zarr results folder. Paste or type the path and press Enter, use the buttons on the right, or drop the file onto the viewer. If a .tif already has a &lt;name&gt;.ome.zarr folder next to it, its saved results and metadata are loaded too; otherwise that folder is created, and all results of this image are saved there.</p>"))
        self.btn_search.setToolTip(_translate("Form", "<p>Choose a .tif/.tiff image or movie in a file dialog and open it straight away. Results saved earlier in the &lt;name&gt;.ome.zarr folder next to it are shown again.</p>"))
